      "favorited" : false,
      "full_text" : "@ku1zu0 太理想化了，我有一任前任，都已经见家长的程度了，在偶尔聊到过去前任的时候一直装作痛苦,甚至还装出发抖的模样，说着给带来了多少的伤痛，结果呢，要不是我深挖一点，要不是我心思慎密程度够高，就差点娶了一个被强奸后(自述)给人知三当三，而且一直还保留联系。如今道德水准越来越低该探究的不能少.",
      "lang" : "zh",
