      "full_text" : "@nyanyakodayo 我内心不够强大，不管过了多久看到类似的经历都会把我自己鞭尸一遍，以前没什么动力的时候还会以“在怎么也要过的比这些人渣好”，现在更多的是像个小人一样内心嘀咕诅咒人渣受到恶报吧。什么时候进入下一段我才能放下吧，但是进入下一段的勇气估计不会有了，希望自己不会为了好受点走极端也成为人渣吧。",
