      "full_text" : "外卖刚才给我打电话说我餐被偷了，本来以为好吧这事也轮到我头上了，后来看名字和照片才发现是我初中同学，他以前经常来我家玩知道我家，也是在进小区后才打电话说餐被偷了，后续处理他也不想走正常流程，想私自退给我。我明白餐没有被偷，只能说男人要好点面，大家都不容易",
