      "possibly_sensitive" : false,
      "created_at" : "Sun Dec 01 03:51:29 +0000 2024",
      "favorited" : false,
      "full_text" : "成绩比预想的好，一年没跑，10月下旬才开始想恢复，跑量200km都没有，本来跑前几天还在想都没好好训练，饮食从恢复开始反而还长胖了，都不想去丢人，本来准备5分完赛就行，发现还能顶就顶下来了，还行哈，至少是超出我预期的。 https://t.co/QTJQ4HXEie",
      "lang" : "zh",
