      "created_at" : "Mon Jan 01 04:38:13 +0000 2024",
      "favorited" : false,
      "full_text" : "还是当做仪式感完成一个20.24，停跑了一段时间已经变成渣渣体能了，边跑跑边拍拍能跑完也是属于吃老本了，这老本也不够厚实，跑完膝盖竟然会痛，激进不冒进，这次引以为戒，也是希望大家都努力生活，健康平安 https://t.co/lDJTTpejsM",
