      "full_text" : "还是有点焦虑的，目前工作是上3休3，上的3天是完全不能运动的状态，休的3天能抽空，但因为谈恋爱了每次都晚归很少有空，换pace3后唯一两次跑步还是不约会的日子但还是去见见女友，从我家跑到她家然后江边散步..按这频率都跑1休5了..只能说慢慢调整了，尽量抽空了，或者努力加油把女友变老婆=。= https://t.co/siisciFP4c",
