      "favorited" : false,
      "full_text" : "这个时期跑步是很舒服的一件事，秋来桂花香，傍晚雨后江边的公园，充满了桂花香，空旷却又不觉得孤独，没人的足球场亮着的灯，渡江大桥下的铁轨声，我的脚步声。微光照在周边绿地的红色彼岸花上。而我在前行。跑完之后洗个澡，来一杯，大概没有比这更浪漫又酷的事情了吧。 https://t.co/DRinsbAscd",
