      "favorited" : false,
      "full_text" : "旅游回来第一天，中午的时候看到一位up的视频分享，尝试了下高温，小米天气37°的温度下跑步，11公里陆陆续续暂停休息了半个多小时的情况下都给我干的半死不活。旅游回来我觉得我会至少胖3斤，跑完这个11公里，体重比之前瘦3斤，这倒是让我很意外。 https://t.co/2LdgGIoWw2",
      "lang" : "zh",
